  "CREATE TABLE [ProposedMotion] (\n  [id] INTEGER PRIMARY KEY AUTOINCREMENT,\n  [CouncilID] INTEGER NOT NULL,\n  [TargetMeetingID] INTEGER NOT NULL,\n  [SourceType] TEXT NOT NULL,\n  [SourceRecordID] INTEGER,\n  [MotionText] TEXT NOT NULL,\n  [PresenterMemberID] INTEGER NOT NULL,\n  [AllocatedMinutes] INTEGER NOT NULL DEFAULT 5,\n  [VoteResult] TEXT NOT NULL DEFAULT 'Pending',\n  [BallotOpenedAt] TEXT,\n  FOREIGN KEY ([CouncilID]) REFERENCES [Council]([id]),\n  FOREIGN KEY ([TargetMeetingID]) REFERENCES [Meeting]([id]),\n  FOREIGN KEY ([PresenterMemberID]) REFERENCES [Member]([id])\n);",
  "CREATE TABLE [GLAccount] (\n  [id] INTEGER PRIMARY KEY AUTOINCREMENT,\n  [CouncilID] INTEGER NOT NULL,\n  [AccountName] TEXT NOT NULL,\n  [AccountType] TEXT NOT NULL,\n  [ParentAccountID] INTEGER,\n  [IsVirtualGoal] INTEGER NOT NULL DEFAULT 0,\n  [TargetGoalAmount] REAL NOT NULL DEFAULT 0,\n  FOREIGN KEY ([CouncilID]) REFERENCES [Council]([id]),\n  FOREIGN KEY ([ParentAccountID]) REFERENCES [GLAccount]([id])\n);",
  "CREATE TABLE [JournalEntry] (\n  [id] INTEGER PRIMARY KEY AUTOINCREMENT,\n  [CouncilID] INTEGER NOT NULL,\n  [GLAccountID] INTEGER NOT NULL,\n  [DateLogged] TEXT NOT NULL,\n  [Description] TEXT NOT NULL,\n  [DebitAmount] REAL NOT NULL DEFAULT 0,\n  [CreditAmount] REAL NOT NULL DEFAULT 0,\n  [LinkedEventID] INTEGER,\n  [LinkedMeetingID] INTEGER,\n  [IsBankReconciled] INTEGER NOT NULL DEFAULT 0,\n  [CheckNumber] TEXT,\n  [TransactionID] TEXT NOT NULL,\n  FOREIGN KEY ([CouncilID]) REFERENCES [Council]([id]),\n  FOREIGN KEY ([GLAccountID]) REFERENCES [GLAccount]([id]),\n  FOREIGN KEY ([LinkedEventID]) REFERENCES [Event]([id]),\n  FOREIGN KEY ([LinkedMeetingID]) REFERENCES [Meeting]([id])\n);",
  "CREATE TABLE [LiveAttendance] (\n  [id] INTEGER PRIMARY KEY AUTOINCREMENT,\n  [CouncilID] INTEGER NOT NULL,\n  [MeetingID] INTEGER NOT NULL,\n  [MemberID] INTEGER NOT NULL,\n  [CheckedInAt] TEXT NOT NULL,\n  FOREIGN KEY ([CouncilID]) REFERENCES [Council]([id]),\n  FOREIGN KEY ([MeetingID]) REFERENCES [Meeting]([id]),\n  FOREIGN KEY ([MemberID]) REFERENCES [Member]([id])\n);",
  "CREATE TABLE [BallotVote] (\n  [id] INTEGER PRIMARY KEY AUTOINCREMENT,\n  [CouncilID] INTEGER NOT NULL,\n  [ProposedMotionID] INTEGER NOT NULL,\n  [AnonymousBallotHash] TEXT NOT NULL,\n  [VoteSelection] TEXT NOT NULL,\n  [CastAt] TEXT NOT NULL,\n  FOREIGN KEY ([CouncilID]) REFERENCES [Council]([id]),\n  FOREIGN KEY ([ProposedMotionID]) REFERENCES [ProposedMotion]([id])\n);",
  "CREATE TABLE [MeetingAgendaItem] (\n  [id] INTEGER PRIMARY KEY AUTOINCREMENT,\n  [CouncilID] INTEGER NOT NULL,\n  [MeetingID] INTEGER NOT NULL,\n  [SectionKey] TEXT NOT NULL,\n  [SortOrder] INTEGER NOT NULL DEFAULT 0,\n  [LineMarkdown] TEXT NOT NULL,\n  [SpeakerRoleID] INTEGER,\n  [SpeakerMemberID] INTEGER,\n  [SpeakerLabel] TEXT,\n  [ProposedMotionID] INTEGER,\n  [LinkedEventID] INTEGER,\n  [LastEditedByMemberID] INTEGER,\n  [LastEditedAt] TEXT,\n  FOREIGN KEY ([CouncilID]) REFERENCES [Council]([id]),\n  FOREIGN KEY ([MeetingID]) REFERENCES [Meeting]([id]),\n  FOREIGN KEY ([SpeakerRoleID]) REFERENCES [Role]([id]),\n  FOREIGN KEY ([SpeakerMemberID]) REFERENCES [Member]([id]),\n  FOREIGN KEY ([ProposedMotionID]) REFERENCES [ProposedMotion]([id]),\n  FOREIGN KEY ([LinkedEventID]) REFERENCES [Event]([id]),\n  FOREIGN KEY ([LastEditedByMemberID]) REFERENCES [Member]([id])\n);",
